=== FILE: css/styles.css ===
/* Basic accessible stylesheet for the replica site */
:root {
  --color-bg: #fafafa;
  --color-fg: #222;
  --color-primary: #0066cc;
  --color-primary-dark: #004c99;
  --color-muted: #666;
  --color-border: #ddd;
  --color-bg-invert: #fff;
  --radius: 4px;
  --transition: 0.2s ease-in-out;
}

/* Reset */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html {
  font-size: 100%;
  scroll-behavior: smooth;
}
body {
  margin: 0;
  font-family: system-ui, sans-serif;
  line-height: 1.5;
  background-color: var(--color-bg);
  color: var(--color-fg);
}
img {
  max-width: 100%;
  height: auto;
  display: block;
}
a {
  color: var(--color-primary);
  text-decoration: underline;
}
a:hover,
a:focus {
  color: var(--color-primary-dark);
}
button {
  cursor: pointer;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--color-primary);
  color: var(--color-bg-invert);
  padding: 8px 16px;
  z-index: 100;
}
.skip-link:focus {
  top: 0;
}

/* Layout containers */
header,
nav,
main,
footer {
  padding: 1rem;
}
.site-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--color-border);
  background: var(--color-bg-invert);
}
.site-logo {
  font-size: 1.25rem;
  font-weight: 600;
  text-decoration: none;
  color: var(--color-fg);
}
.primary-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.primary-nav a {
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius);
  text-decoration: none;
}
.primary-nav a:hover,
.primary-nav a:focus,
.primary-nav a[aria-current="page"] {
  background: var(--color-primary);
  color: var(--color-bg-invert);
}

/* Hero band */
.hero-band {
  background: var(--color-bg-invert);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  margin: 1rem 0;
  overflow: hidden;
}
.hero-band img {
  width: 100%;
  height: auto;
}

/* Content bands */
.content-band {
  margin: 1rem 0;
}
.content-band > h2 {
  margin-bottom: 0.5rem;
}

/* Card grid */
.card-grid {
  display: grid;
  gap: 1rem;
}
@media (min-width: 480px) {
  .card-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (min-width: 768px) {
  .card-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}
.card {
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 1rem;
  background: var(--color-bg-invert);
}
.card img {
  margin-bottom: 0.5rem;
}

/* Sidebar */
.sidebar {
  margin-top: 2rem;
}
.sidebar h3 {
  margin-bottom: 0.5rem;
}
.sidebar ul {
  list-style: none;
  padding: 0;
}
.sidebar li {
  margin-bottom: 0.25rem;
}
.sidebar a {
  text-decoration: none;
}
.sidebar a:hover,
.sidebar a:focus {
  text-decoration: underline;
}

/* Modal / Lightbox */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  display: none;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}
.modal-backdrop[aria-hidden="false"] {
  display: flex;
}
.modal-content {
  background: var(--color-bg-invert);
  border-radius: var(--radius);
  padding: 1.5rem;
  max-width: 90%;
  max-height: 80vh;
  overflow: auto;
  position: relative;
}
.modal-content img {
  width: 100%;
  height: auto;
  border-radius: var(--radius);
}
.modal-close {
  position: absolute;
  top: 0.5rem;
  right: 0.5rem;
  background: transparent;
  border: none;
  font-size: 1.5rem;
  line-height: 1;
  color: var(--color-fg);
  padding: 0.25rem;
}

/* Newsletter toast */
.toast {
  position: fixed;
  bottom: 1rem;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-primary);
  color: var(--color-bg-invert);
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius);
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition);
}
.toast.visible {
  opacity: 0.9;
  pointer-events: auto;
}

/* Footer */
.site-footer {
  border-top: 1px solid var(--color-border);
  margin-top: 2rem;
  font-size: 0.875rem;
  color: var(--color-muted);
}
.site-footer a {
  color: var(--color-muted);
  text-decoration: underline;
}
.site-footer a:hover,
.site-footer a:focus {
  color: var(--color-primary);
}

/* Focus visible */
:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* Reduce motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
