@media (min-width: 768px) {
  .card-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}
.card {
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 1rem;
  background: var(--color-bg-invert);
}
.card img {
  margin-bottom: 0.5rem;
}

/* Sidebar */
.sidebar {
  margin-top: 2rem;
}
.sidebar h3 {
  margin-bottom: 0.5rem;
}
.sidebar ul {
  list-style: none;
  padding: 0;
}
.sidebar li {
  margin-bottom: 0.25rem;
}
.sidebar a {
  text-decoration: none;
}
.sidebar a:hover,
.sidebar a:focus {
  text-decoration: underline;
}

/* Modal / Lightbox */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  display: none;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}
.modal-backdrop[aria-hidden="false"] {
  display: flex;
}
.modal-content {
  background: var(--color-bg-invert);
  border-radius: var(--radius);
  padding: 1.5rem;
  max-width: 90%;
  max-height: 80vh;
  overflow: auto;
  position: relative;
}
.modal-content img {
  width: 100%;
  height: auto;
  border-radius: var(--radius);
}
.modal-close {
  position: absolute;
  top: 0.5rem;
  right: 0.5rem;
  background: transparent;
  border: none;
  font-size: 1.5rem;
  line-height: 1;
  color: var(--color-fg);
  padding: 0.25rem;
}

/* Newsletter toast */
.toast {
  position: fixed;
  bottom: 1rem;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-primary);
  color: var(--color-bg-invert);
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius);
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition);
}
.toast.visible {
  opacity: 0.9;
  pointer-events: auto;
}

/* Footer */
.site-footer {
  border-top: 1px solid var(--color-border);
  margin-top: 2rem;
  font-size: 0.875rem;
  color: var(--color-muted);
}
.site-footer a {
  color: var(--color-muted);
  text-decoration: underline;
}
.site-footer a:hover,
.site-footer a:focus {
  color: var(--color-primary);
}

/* Carousel buttons */
.carousel-prev,
.carousel-next {
  background: var(--color-bg-invert);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 0.5rem;
  cursor: pointer;
  min-width: 44px;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.carousel-prev:hover,
.carousel-next:hover,
.carousel-prev:focus,
.carousel-next:focus {
  background: var(--color-primary);
  color: var(--color-bg-invert);
}

/* Focus visible */
:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* Reduce motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
